INSERT IGNORE INTO material_upload_session (
    id, owner_type, owner_key, idempotency_key, display_name, target_scope_type, target_scope_key,
    target_retention_class, new_version_of_material_id, expected_size, expected_sha256, declared_mime,
    quarantine_bucket, quarantine_key, policy_expires_at, state, generation
) VALUES (
    #{id}, #{ownerType}, #{ownerKey}, #{idempotencyKey}, #{displayName}, #{targetScopeType},
    #{targetScopeKey}, #{targetRetentionClass}, #{newVersionOfMaterialId}, #{expectedSize},
    #{expectedSha256}, #{declaredMime}, #{quarantineBucket}, #{quarantineKey}, #{policyExpiresAt},
    #{state}, #{generation}
)

mapper.update:
UPDATE material_upload_session
SET state = 'EXPIRED', generation = generation + 1
WHERE id = #{id} AND state = 'CREATED' AND generation = #{expectedGeneration}

mapper.select:
SELECT COUNT(*) FROM material_upload_session
WHERE owner_type = #{ownerType} AND owner_key = #{ownerKey}
  AND state IN ('OBJECT_VERSION_PINNED', 'PROCESSING')

SELECT upload_count FROM material_upload_rate_bucket
WHERE subject_type = #{subjectType} AND subject_key = #{subjectKey} AND hour_bucket = #{hourBucket}
FOR UPDATE

SELECT COUNT(*) FROM (
    SELECT c.conversation_id FROM conversation_source_context c
    JOIN diagram d ON d.id = c.diagram_id AND d.user_id = c.owner_key AND d.deleted = 0
    WHERE c.conversation_id = #{conversationId} AND c.owner_key = #{ownerKey}
    UNION ALL
    SELECT m.session_id FROM diagram_conversation_message m
    JOIN diagram d ON d.id = m.diagram_id AND d.user_id = m.user_id AND d.deleted = 0
    WHERE m.session_id = #{conversationId} AND m.user_id = #{ownerKey}
    LIMIT 1
) owned_conversation

SELECT COUNT(*) FROM material
WHERE id = #{materialId} AND owner_type = #{ownerType} AND owner_key = #{ownerKey}
  AND lifecycle_state = 'ACTIVE'

mapper.update:
UPDATE material_upload_session
SET state = 'PROCESSING', generation = generation + 1
WHERE id = #{id} AND state = 'OBJECT_VERSION_PINNED' AND generation = #{expectedGeneration}
  AND EXISTS (SELECT 1 FROM material_processing_job j WHERE j.id = #{jobId} AND j.status = 'RUNNING'
      AND j.lease_owner = #{workerId} AND j.fence_token = #{fenceToken}
      AND j.lease_until > UTC_TIMESTAMP(3))

UPDATE material_upload_session
SET state = 'REJECTED', error_code = #{errorCode}, generation = generation + 1
WHERE id = #{id} AND state = 'PROCESSING' AND generation = #{expectedGeneration}
  AND EXISTS (SELECT 1 FROM material_processing_job j WHERE j.id = #{jobId} AND j.status = 'RUNNING'
      AND j.lease_owner = #{workerId} AND j.fence_token = #{fenceToken}
      AND j.lease_until > UTC_TIMESTAMP(3))
